static const unsigned int kCubinSize = (unsigned int)sizeof(kCubinData);

static int32_t ceildiv_i32(int32_t n, int32_t d) {
    return (n + d - 1) / d;
}

static CUresult ensure_loaded(void) {
    if (g_function != NULL) return CUDA_SUCCESS;
    (void)kCubinSize;
    CUresult r = cuModuleLoadData(&g_module, kCubinData);
    if (r != CUDA_SUCCESS) return r;
    r = cuModuleGetFunction(&g_function, g_module, kFuncSymbol);
    if (r != CUDA_SUCCESS) return r;
    return cuFuncSetAttribute(
        g_function,
        CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES,
        24576
    );
}

CUresult gated_delta_rule_prefill_chunk_recompute_sm100_cuda(
    const uint16_t *k,
    const uint16_t *v,
    const float *beta,
    uint16_t *w,
    uint16_t *u,
    const uint16_t *a_inv,
    const float *g_cumsum,
    int32_t seq_len,
    int32_t num_value_heads,
    CUstream stream
) {

    CUresult r = ensure_loaded();
    if (r != CUDA_SUCCESS) return r;

    int32_t args_hv = num_value_heads;
    int32_t args_hv_1 = num_value_heads;
    int32_t args_hv_2 = num_value_heads;
    int32_t args_hv_3 = num_value_heads;
    int32_t args_hv_4 = num_value_heads;
    int32_t args_hv_5 = num_value_heads;
    int32_t args_hv_6 = num_value_heads;
    int32_t args_num_value_heads = num_value_heads;
    int32_t args_seq_len = seq_len;
    int32_t args_seq_len_1 = seq_len;
    int32_t args_seq_len_2 = seq_len;
    int32_t args_seq_len_3 = seq_len;
    int32_t args_seq_len_4 = seq_len;
    int32_t args_seq_len_5 = seq_len;
    int32_t args_seq_len_6 = seq_len;
    int32_t args_seq_len_7 = seq_len;

    void *args[] = {
        &a_inv,
        &beta,
        &g_cumsum,
        &k,
        &u,
        &v,
        &w,
        &args_hv,
        &args_hv_1,
        &args_hv_2,
        &args_hv_3,
        &args_hv_4,
        &args_hv_5,
        &args_hv_6,
        &args_num_value_heads,
        &args_seq_len,
        &args_seq_len_1,
        &args_seq_len_2,
        &args_seq_len_3,
        &args_seq_len_4,
        &args_seq_len_5,
        &args_seq_len_6,
        &args_seq_len_7,
    };

    int grid_x = ceildiv_i32(seq_len, 64);
    int grid_y = num_value_heads;
    int grid_z = 1;

    return cuLaunchKernel(
        g_function,
        grid_x, grid_y, grid_z,
        128, 1, 1,
        24576, stream, args, NULL
    );
}
